insert into section_rich_text (section_id, body_text) values ('sec_tee_about', 'Tee Off powered by Topgolf Swing Suite is a dining and entertainment venue that features golf-simulation games and a variety of other virtual sports and games using state-of-the-art technology. This fun and interactive restaurant is located at The Wharf in sunny Orange Beach, Alabama and is ideal for team-building events, corporate outings, happy hours, birthday parties and more. Topgolf Swing Suite and its Full Swing golf simulator provide endless opportunities for fun. Whether you''re an aspiring golf pro or picking up a club for the first time, Topgolf is for everyone.');
