insert into section_cards (section_id, title, subtitle, description, badge_text, price_text, sort_order) values ('sec_tee_packages', 'Par-Tee Animals', 'Kids Package', 'Kids Party Package. Includes 2 hours of Topgolf Swing Suite simulation, 8 hotdogs or 16 chicken tenders, large basket of fries, 2 pitchers of fountain drinks, and birthday decorations.', '⏱ 2 hours', '$360', 1);
insert into section_cards (section_id, title, subtitle, description, badge_text, price_text, sort_order) values ('sec_tee_packages', 'Tee Off Titans', 'Non-Alcoholic Adult', 'Includes 2 hours of Topgolf Swing Suite simulation, 50 wings (5 choices of wing sauce + 10 dipping sauces), large basket of fries, 2 pitchers of fountain drinks, and birthday decorations.', '⏱ 2 hours', '$400', 2);
insert into section_cards (section_id, title, subtitle, description, badge_text, price_text, sort_order) values ('sec_tee_packages', 'Tee Totalers', 'Alcoholic Adult', 'Includes 2 hours of Topgolf Swing Suite simulation, 50 wings (5 choices of wing sauce + 10 dipping sauces), large basket of fries, beer tower with any beer, and birthday decorations.', '⏱ 2 hours', '$425', 3);
insert into section_cards (section_id, title, subtitle, description, badge_text, price_text, sort_order) values ('sec_tee_league', 'Golf League', '📅 Sundays–Wednesdays starting Feb 1 | 12 weeks · Teams of 2, scramble format', 'Competitive 12-week golf league. Teams of 2, scramble format. Experience exciting weekly 9-hole matches on different courses using state-of-the-art golf simulators. Our league features a comprehensive point system rewarding both match victories and low scores.', '✓ 10% off food & drinks all season, ✓ Weekly standings posted online, ✓ Champion: $500 in gift cards, ✓ Runner-up: $250 in gift cards, ✓ Single-elimination playoffs, ✓ Substitute players welcome', '$250/team', 1);
insert into section_cards (section_id, title, subtitle, description, badge_text, price_text, sort_order) values ('sec_tee_book_a_bay', 'Swing Suite Rental', '👥 Up to 8 participants per bay', 'TOPGOLF Swing Suite rental at standard rate. Access to golf simulators and virtual sports games.', NULL, '$75/hr', 1);
insert into section_cards (section_id, title, subtitle, description, badge_text, price_text, sort_order) values ('sec_tee_events', 'Birthday & Group Parties', 'Available Daily', 'Book a private bay for birthdays, corporate outings, bachelor/bachelorette parties and team-building events. Party packages include simulator time, food, and drinks.', '📌 Reservation required', NULL, 1);
